#!date=2026-11-21
#!format=sgmodule

[URL Rewrite]
request if ${url} ~= /^https?:\/\/kaola-haitao\.oss\.kaolacdn.com\/.+?_\d{3,4}_\d{4}\.jpg\?x-oss-process=image\/resize,m_mfit,w_\d{3,4},h_\d{4}\/format,webp\/quality,Q_85/i then reject(200)
request if ${url} ~= /^https?:\/\/sp\.kaola\.com\/api\/openad/i then reject(200)
request if ${url} ~= /^https?:\/\/gw\.kaola\.com\/gw\/dgmobile\/newOpenAd/i then reject(404)

[MITM]
hostname = %APPEND% kaola-haitao.oss.kaolacdn.com, sp.kaola.com, gw.kaola.com
